  "chunks": [
    {
      "chunk_type": "opening",
      "arabic_text": "وَقَالَ أَبُو جَعْفَرٍ عَلَيْهِ السَّلَامُ:",
      "translations": {
        "en": "Abu Ja‘far عليه السلام said:"
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "«أَوَّلُ وَقْتِ الْجُمُعَةِ سَاعَةَ تَزُولُ الشَّمْسُ إِلَى أَنْ تَمْضِيَ سَاعَةٌ فَحَافِظْ عَلَيْهَا فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَ آلِهِ قَالَ",
      "translations": {
        "en": "“The beginning of the time of Jumu‘ah is from the moment the sun declines until an hour passes, so preserve it carefully, for the Messenger of Allah صلى الله عليه وآله وسلم said:"
      }
    },
    {
      "chunk_type": "closing",
      "arabic_text": "«لَا يَسْأَلُ اللَّهَ عَزَّ وَ جَلَّ عَبْدٌ فِيهَا خَيْرًا إِلَّا أَعْطَاهُ».",
      "translations": {
        "en": "‘No servant asks Allah, Mighty and Majestic, for any good therein except that He gives it to him.’”
      }
    }
  ],
  "translations": {
    "en": {
      "summary": "This hadith defines the opening time of the Friday prayer as beginning at the sun’s decline and extending for about an hour, urging believers to observe it carefully. It also highlights that this time is especially blessed, such that any servant who asks Allah for good during it is granted it.",
      "seo_question": "When does the time of Jumu‘ah begin, and is it a special time for du‘a?",
      "key_terms": {
        "أَوَّلُ": "the beginning or earliest part of something",
        "وَقْتِ": "the appointed time of an act of worship",
        "الْجُمُعَةِ": "the Friday prayer and its designated time",
        "تَزُولُ": "declines from the meridian; passes zenith",
        "فَحَافِظْ": "so observe and preserve carefully",
        "خَيْرًا": "any good or beneficial matter asked from Allah",
        "أَعْطَاهُ": "He grants it to him"
      }
    }
  },
